from pathlib import Path
import json,csv,hashlib,numpy as np
B=Path(__file__).parent;D=B.parent
R=json.loads((B/'raw-evidence/raw-events.json').read_text());I={x['tic']:x for x in json.loads((B/'raw-evidence/independent-results.json').read_text())};G=json.loads((B/'gaia-geometry.json').read_text());S=json.loads((B/'source-review.json').read_text());C={x['tic']:x for x in json.loads((B/'catalogue-review.json').read_text())};Q=[r for r in csv.DictReader((D/'queue.csv').open()) if r['batch']=='4'];out=[]
for q in Q:
 t=q['tic'];r=R[t];g=G[t];s=S[t];i=I[t];ev=[x for x in r['events'] if 'tc'in x];ep=r['representative_ephemeris'];ip=i.get('measurements',[]);complete=bool(ip);verdict='CONFIRMED' if complete and t!='39069184' else 'PLAUSIBLE';geo=g['conjunction'][g['closest_kind']];depths=[x['depth']*1000 for x in ev];ind=[x['depth']*1000 for x in ip]
 row=dict(position=q['position'],tic=t,physical_verdict=verdict,execution_completion='complete' if complete else 'incomplete: independent pipeline unavailable',novelty_status=C[t]['scoped_prior_eb_status'],raw_events=len(ev),phot_period_d=ep['period_d'],timing_rms_min=ep['residual_rms_min'],raw_depth_median_ppt=float(np.median(depths)),gaia_period_d=g['gaia_P'],gaia_period_sigma=g['period_difference_gaia_sigma'],conjunction_offset_d=geo['offset_d'],conjunction_linear_cov_error_d=geo['covariance_linear_error_d'],diff_target_offset_arcsec=s['target_distance_arcsec'],capable_neighbours=len(s['capable']),independent_pipeline=i.get('provenance','unavailable'),independent_sector=i.get('sector',''),independent_depths_ppt=json.dumps(ind),note='Representative measurements; period conditional on search cycle counts; uncertainty and characterization limitations retained.')
 out.append(row)
 text=f'''# TIC {t}\n\n{verdict}. Execution: {row['execution_completion']}. Scoped novelty: {row['novelty_status']}.\n\nRaw QLP SAP_FLUX with QUALITY=0 yields {len(ev)} representative events in sectors {sorted(set(x['sector'] for x in ev))}; depths {min(depths):.2f}–{max(depths):.2f} ppt. Quadratic local baseline plus trapezoid, native cadence, derives P={ep['period_d']:.9f} d from event centres. Timing RMS={ep['residual_rms_min']:.3f} min; unweighted and conditional on the search cycle counts, without a fitted uncertainty. For two-event solutions, near-zero RMS is algebraic and is not a precision claim. The lead inspected the raw event panel.\n\n{s['source_assessment']}\n\n'''
 if t=='309981203':text+='QLP fitted depth varies across sectors (about69-92 ppt); pixel aperture depths are lower (about45 ppt). Aperture dilution/systematics are retained; depth consistency is not assumed.\n\n'
 for n in s['capable']:text+=f"Capable neighbour Gaia DR3 {n['source_id']}: catalog separation {n['sep']:.2f} arcsec, required loss {100*n['depth_needed']:.2f}%, own-pixel loss {100*n['frac_loss_at_pixel']:.2f}%, deficit distance {n['deficit_distance_arcsec']:.2f} arcsec. Pixel losses include mixed source flux and are supporting spatial diagnostics.\n\n"
 if ip:
  text+=f"{i['provenance']} sector {i['sector']} confirms event depths {', '.join(f'{x:.2f}' for x in ind)} ppt. "
  if 'TESScut' in i['provenance']:
   text+="Independent 3x3 target aperture with per-cadence faint-pixel background; core medians versus local pre/post baseline, without formal errors or dilution correction. This uses the same TESS images through an independent extraction pipeline, not an independent observation. Gaia coordinates projected through the cutout WCS verify the target position and header sector. "
  else:
   text+="Fixed QLP event shape with independently extracted SAP flux; uninflated formal depth errors (ppt): "+', '.join(str(round(1000*x['formal_error'],3)) for x in ip)+". FITS TIC/sector headers and padded TIC URI identity pass. "
  text+="Input paths/URIs and SHA256 are preserved in raw-evidence/independent-results.json.\n\n"
 else:text+=f"Independent pipeline retrieval unresolved: {i.get('error')}. This limits execution completion rather than demonstrating a physical contradiction.\n\n"
 text+=f"Gaia SB1 P={g['gaia_P']:.9f} d, difference {g['period_difference_gaia_sigma']:.2f} Gaia sigma. Closest edge-on conjunction {g['closest_kind']} offset {geo['offset_d']:.5f} d versus linear full SB1 covariance error {geo['covariance_linear_error_d']:.5f} d; no significant timing contradiction. Observed median duration {g['observed_duration_hours_median']:.2f} h versus approximate central main-sequence feasibility {g['central_duration_hours_approx']:.2f} h; mass function {g['mass_function']:.5f} solar masses. This is a geometry feasibility check, not a fitted stellar solution or measured inclination. Linear propagation can be approximate for nearly circular orbits.\n\nSeven-scope central catalogue matrix status is {C[t]['scoped_prior_eb_status']}; coverage is {C[t]['coverage_complete']}. See the target-specific matches in catalogue-review.json. SIMBAD SB* alone is not an EB type; Kostov table2 is unvetted. Historical five-arcsecond batteries retain condensed rather than raw per-query receipts; VSX/ASAS-SN cones are 60 arcsec. Scope and alternate-identity limitations apply. See catalogue-review.json and ../shared-catalogues/README.md for exact coverage.\n\nEvidence: raw-evidence/raw-events.json, raw-evidence/qlp-manifest.json, source-review.json, gaia-geometry.json, catalogue-review.json, and provenance hashes.\n"
 (B/f'TIC-{t}.md').write_text(text)
with (B/'RESULTS.csv').open('w',newline='') as f:w=csv.DictWriter(f,list(out[0]));w.writeheader();w.writerows(out)
print([(x['tic'],x['physical_verdict']) for x in out])


